/// Pool flags that add or remove a joker (Gros Michel's extinction).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum PoolFlag {
    /// In the pool only while the flag is not set.
    NotIf(&'static str),
    /// In the pool only once the flag is set.
    OnlyIf(&'static str),
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct JokerInfo {
    pub kind: JokerKind,
    pub key: &'static str,
    pub name: &'static str,
    /// 1 Common, 2 Uncommon, 3 Rare, 4 Legendary.
    pub rarity: u8,
    pub cost: i64,
    pub blueprint_compat: bool,
    pub eternal_compat: bool,
    pub perishable_compat: bool,
    pub unlocked_by_default: bool,
    /// Only in pools once a card with this enhancement exists in the deck.
    pub enhancement_gate: Option<Enhancement>,
    pub pool_flag: Option<PoolFlag>,
}

