impl JokerKind {
    pub const ALL: [JokerKind; N_JOKERS] = {
        let mut a = [JokerKind::Joker; N_JOKERS];
        let mut i = 0;
        while i < N_JOKERS {
            a[i] = JOKERS[i].kind;
            i += 1;
        }
        a
    };

    pub fn index(self) -> usize {
        self as usize
    }

    pub fn info(self) -> &'static JokerInfo {
        &JOKERS[self as usize]
    }

    pub fn key(self) -> &'static str {
        self.info().key
    }

    pub fn name(self) -> &'static str {
        self.info().name
    }

    pub fn rarity(self) -> u8 {
        self.info().rarity
    }

    pub fn from_key(key: &str) -> Option<JokerKind> {
        JOKERS.iter().find(|j| j.key == key).map(|j| j.kind)
    }
}
